CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK(length(full_name)<=100), email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '' CHECK(length(phone)<=20), address text NOT NULL DEFAULT '' CHECK(length(address)<=300), city text NOT NULL DEFAULT '' CHECK(length(city)<=100), postal_code text NOT NULL DEFAULT '' CHECK(length(postal_code)<=10), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email) VALUES(NEW.id,coalesce(NEW.email,'')); RETURN NEW; END $$;
CREATE TRIGGER create_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.products(id text PRIMARY KEY CHECK(length(id)<=100), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150), price numeric(12,3) NOT NULL CHECK(price>=0), category text NOT NULL CHECK(category IN ('Equipment','Accessories','Apparel','Racks & storage')), image text NOT NULL, subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', options jsonb NOT NULL DEFAULT '["Standard"]', details jsonb NOT NULL DEFAULT '[]', stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), is_active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_catalog ON public.products FOR SELECT TO anon,authenticated USING(is_active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_catalog ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.store_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), delivery_fee numeric(12,3) NOT NULL DEFAULT 0 CHECK(delivery_fee>=0), store_name text NOT NULL DEFAULT 'Iron Soul', contact_phone text NOT NULL DEFAULT '', low_stock_threshold integer NOT NULL DEFAULT 5 CHECK(low_stock_threshold>=0));
GRANT SELECT ON public.store_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.store_settings TO authenticated; GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_settings ON public.store_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.store_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.drivers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(length(phone)<=20), is_active boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.drivers TO authenticated; GRANT ALL ON public.drivers TO service_role;
ALTER TABLE public.drivers ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_drivers ON public.drivers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, customer_name text NOT NULL, customer_email text NOT NULL DEFAULT '', customer_phone text NOT NULL, shipping_address jsonb NOT NULL, items jsonb NOT NULL, total_amount numeric(12,3) NOT NULL, delivery_fee numeric(12,3) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Confirmed','Processing','Shipped','Delivered','Cancelled','Returned','Failed')), payment_status text NOT NULL DEFAULT 'Pending' CHECK(payment_status IN ('Pending','Paid','Refunded')), source text NOT NULL DEFAULT 'Website' CHECK(source IN ('Website','Store','Instagram')), driver_id uuid REFERENCES public.drivers(id), delivery_date date, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_orders ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX orders_user ON public.orders(user_id,created_at DESC);
CREATE TABLE public.order_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), status text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_events TO authenticated; GRANT ALL ON public.order_events TO service_role;
ALTER TABLE public.order_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_events ON public.order_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders WHERE orders.id=order_id AND (orders.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.newsletter_subscribers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL CHECK(length(email)<=255), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.newsletter_subscribers TO authenticated; GRANT ALL ON public.newsletter_subscribers TO service_role;
ALTER TABLE public.newsletter_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_subscribers ON public.newsletter_subscribers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.place_cod_order(customer jsonb, lines jsonb, sale_source text DEFAULT 'Website', linked_user uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE p public.products; line jsonb; quantity integer; calculated numeric=0; fee numeric=0; resolved jsonb='[]'; oid uuid; owner_id uuid; admin boolean=public.has_role(auth.uid(),'admin');
BEGIN
IF sale_source NOT IN ('Website','Store','Instagram') OR (sale_source<>'Website' AND NOT admin) OR (linked_user IS NOT NULL AND NOT admin) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF jsonb_typeof(lines)<>'array' OR jsonb_array_length(lines) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Bag must contain 1 to 50 lines'; END IF;
IF length(trim(coalesce(customer->>'full_name',''))) NOT BETWEEN 2 AND 100 OR coalesce(customer->>'phone','') !~ '^(\+216)?[0-9]{8}$' OR length(trim(coalesce(customer->>'address',''))) NOT BETWEEN 3 AND 300 OR length(trim(coalesce(customer->>'city',''))) NOT BETWEEN 2 AND 100 OR length(coalesce(customer->>'email',''))>255 OR length(coalesce(customer->>'postal_code',''))>10 THEN RAISE EXCEPTION 'Check customer name, Tunisian phone number and delivery address'; END IF;
IF NOT admin AND EXISTS(SELECT 1 FROM public.orders WHERE customer_phone=customer->>'phone' AND created_at>now()-interval '30 seconds') THEN RAISE EXCEPTION 'Please wait before placing another order'; END IF;
FOR line IN SELECT value FROM jsonb_array_elements(lines) ORDER BY value->>'productId' LOOP
quantity=(line->>'quantity')::integer;
IF quantity NOT BETWEEN 1 AND 99 THEN RAISE EXCEPTION 'Invalid quantity'; END IF;
SELECT * INTO p FROM public.products WHERE id=line->>'productId' FOR UPDATE;
IF NOT FOUND OR NOT p.is_active OR p.stock<quantity OR NOT(p.options ? (line->>'option')) THEN RAISE EXCEPTION 'Product unavailable or insufficient stock'; END IF;
UPDATE public.products SET stock=stock-quantity WHERE id=p.id;
calculated=calculated+p.price*quantity;
resolved=resolved||jsonb_build_array(jsonb_build_object('productId',p.id,'name',p.name,'price',p.price,'option',line->>'option','quantity',quantity));
END LOOP;
SELECT coalesce(delivery_fee,0) INTO fee FROM public.store_settings WHERE id=1; fee=coalesce(fee,0); IF sale_source='Store' THEN fee=0; END IF;
owner_id=CASE WHEN admin AND sale_source<>'Website' THEN linked_user ELSE auth.uid() END;
INSERT INTO public.orders(user_id,customer_name,customer_email,customer_phone,shipping_address,items,total_amount,delivery_fee,source) VALUES(owner_id,customer->>'full_name',coalesce(customer->>'email',''),customer->>'phone',jsonb_build_object('address',customer->>'address','city',customer->>'city','postalCode',coalesce(customer->>'postal_code',''),'country','Tunisia'),resolved,calculated+fee,fee,sale_source) RETURNING id INTO oid;
INSERT INTO public.order_events(order_id,status) VALUES(oid,'Pending'); RETURN oid;
END $$;
REVOKE ALL ON FUNCTION public.place_cod_order(jsonb,jsonb,text,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.place_cod_order(jsonb,jsonb,text,uuid) TO anon,authenticated;
CREATE FUNCTION public.manage_order(oid uuid,new_status text,new_payment text,new_driver uuid DEFAULT NULL,new_date date DEFAULT NULL,new_notes text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE old public.orders; line jsonb;
BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Not authorized'; END IF;
SELECT * INTO old FROM public.orders WHERE id=oid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
IF length(new_notes)>2000 THEN RAISE EXCEPTION 'Notes too long'; END IF;
IF old.status IN ('Cancelled','Returned') AND new_status<>old.status THEN RAISE EXCEPTION 'Create a new order to reopen a cancelled or returned sale'; END IF;
IF new_status IN ('Cancelled','Returned') AND old.status NOT IN ('Cancelled','Returned') THEN FOR line IN SELECT value FROM jsonb_array_elements(old.items) LOOP UPDATE public.products SET stock=stock+(line->>'quantity')::integer WHERE id=line->>'productId'; END LOOP; END IF;
IF new_payment='Paid' AND new_status<>'Delivered' THEN RAISE EXCEPTION 'Cash is collected only when delivered'; END IF;
UPDATE public.orders SET status=new_status,payment_status=new_payment,driver_id=new_driver,delivery_date=new_date,notes=new_notes,updated_at=now() WHERE id=oid;
INSERT INTO public.order_events(order_id,status,note) VALUES(oid,new_status,new_notes);
END $$;
REVOKE ALL ON FUNCTION public.manage_order(uuid,text,text,uuid,date,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_order(uuid,text,text,uuid,date,text) TO authenticated;
CREATE FUNCTION public.subscribe_newsletter(sub_email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(sub_email)>255 OR sub_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RAISE EXCEPTION 'Invalid email'; END IF; INSERT INTO public.newsletter_subscribers(email) VALUES(lower(sub_email)) ON CONFLICT(email) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.subscribe_newsletter(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.subscribe_newsletter(text) TO anon,authenticated;